package reports

type Exporter struct {              // coordinator facade with injected collaborators
    renderer Renderer
    store    ObjectStore
}

func (e *Exporter) Export(ctx context.Context, req Request) (Result, error) {
    doc := e.renderer.Render(req)
    return e.store.Put(ctx, doc)    // subsystems stay hidden behind small interfaces
}
